def count_distinct(items):
    """Return the number of different items in the list items."""
    return len(set(items))

def repeated_items(items):
    """Return a list, sorted in increasing order, of the different items that appear more than once in the list items."""
    return sorted((x for x in set(items) if items.count(x) > 1))

def all_the_same(items):
    """Return True if all items of the list items are equal to each other (True for an empty list), otherwise False."""
    return len(set(items)) <= 1

def pairwise_sums(a, b):
    """Return a list with a[k] + b[k] for every position k of the lists a and b, which have the same length."""
    return [x + y for x, y in zip(a, b)]

def dot_product(a, b):
    """Return the sum of a[k] * b[k] over every position k of the lists a and b, which have the same length (0 if they are empty)."""
    return sum((x * y for x, y in zip(a, b)))

def common_items(a, b):
    """Return a list of the items of the list a that also appear in the list b, in the order they have in a."""
    return [x for x in a if x in b]

def count_matching_positions(a, b):
    """Return at how many positions the lists a and b, which have the same length, hold equal items."""
    return sum((1 for x, y in zip(a, b) if x == y))

def fibonacci_number(n):
    """Return Fibonacci number n, where numbers 0 and 1 are 0 and 1 and every later one is the sum of the two before it."""
    a, b = (0, 1)
    for g in range(n):
        a, b = (b, a + b)
    return a

def power_of_two_above(n):
    """Return the smallest of the numbers 1, 2, 4, 8, 16 and so on that is greater than n."""
    power = 1
    while power <= n:
        power *= 2
    return power

def remove_character(s, ch):
    """Return the string s without the characters that are equal to the character ch."""
    return s.replace(ch, '')

def replace_spaces_with_dashes(s):
    """Return the string s with every space character replaced by '-'."""
    return s.replace(' ', '-')

def double_every_character(s):
    """Return a string in which every character of the string s is written twice in a row."""
    return ''.join((ch * 2 for ch in s))

def keep_only_digits(s):
    """Return a string made of the characters of the string s that are digits from 0 to 9, in the same order."""
    return ''.join((ch for ch in s if ch.isdigit()))

def replace_vowels_with_star(s):
    """Return the lower-case string s with every vowel (a, e, i, o, u) replaced by '*'."""
    return ''.join(('*' if ch in 'aeiou' else ch for ch in s))

def move_first_to_end(items):
    """Return the list items with its first item moved to the end (an empty list stays empty)."""
    return items[1:] + items[:1]

def move_last_to_front(items):
    """Return the list items with its last item moved to the front (an empty list stays empty)."""
    return items[-1:] + items[:-1]

def swap_first_and_last(items):
    """Return the list items with its first and last items exchanged, where items has at least two items."""
    return [items[-1]] + items[1:-1] + [items[0]]

def rotate_left_by(items, n):
    """Return the list items with its first n items moved to the end in the same order, where n is not larger than its length."""
    return items[n:] + items[:n]

def to_binary_string(n):
    """Return the binary digits of the integer n as a string, where n is not negative (5 gives '101' and 0 gives '0')."""
    return bin(n)[2:]

def binary_to_number(bits):
    """Return the integer whose binary digits are the characters of the string bits, so '101' gives 5."""
    return int(bits, 2)

def count_one_bits(n):
    """Return how many digits 1 the integer n has when it is written in binary, where n is not negative."""
    return bin(n).count('1')

def binary_length(n):
    """Return how many digits the positive integer n has when it is written in binary, so 5 (binary 101) gives 3."""
    return len(bin(n)) - 2

def flip_bits(bits):
    """Return the string bits with every '0' changed to '1' and every '1' changed to '0'."""
    return ''.join(('1' if ch == '0' else '0' for ch in bits))
